"""Portal TI Ellenco. Inicie com: streamlit run app.py"""
import streamlit as st
from html import escape
import unicodedata

st.set_page_config(page_title="Ellenco | Portal de TI", page_icon="🔗", layout="wide")

PORTAIS = [
    ('Chamados TOTVS', 'Suporte', 'Abertura e acompanhamento de chamados.', 'https://suporte.totvs.com/portal/p/10098/customer-portal-dashboard', 'TO'),
    ('Chamados SISMA', 'Suporte', 'Central de atendimento SISMA.', 'https://assisteweb.trace.com.br/TraceGP/indexPopup.jsp', 'SI'),
    ('Meu RH', 'Pessoas', 'Acesso ao portal do colaborador.', 'https://meurh.ellenco.com.br/web/app/RH/PortalMeuRH/#/login', 'RH'),
    ('TAE', 'Documentos', 'Portal de assinatura eletrônica TOTVS.', 'https://totvssign.totvs.app/webapptotvssign/auth/welcome', 'TA'),
    ('Neogrid', 'Documentos', 'Portal de monitoramento fiscal.', 'https://portalmonitoramentototvs.fiscalneogrid.com/', 'NE'),
    ('Trello', 'Organização', 'Quadros, tarefas e projetos.', 'https://trello.com/', 'TR'),
    ('Carol Conect', 'Clockin', 'Conexão Clockin • requer acesso à rede interna.', 'http://100.64.251.231:8880/ui/login', 'CC'),
    ('Carol Backoffice', 'Clockin', 'Acesso ao painel Clockin.', 'https://ellenco.carol.ai/ellenco/apps/clockinapp/12.1.26100000/index.html#/dashboard', 'CB'),
    ('Carol ADM', 'Clockin', 'Administração do ambiente Carol.', 'https://ellenco.carol.ai/auth/login?env=ellenco&redirect=%2Fellenco%2Fcarol-ui%2Fcarol-app%2F8898a01454d745539c7f7ea9450fb6b9%2Fsettings', 'CA'),
]

st.markdown("""<style>
.stApp{background:radial-gradient(ellipse at 85% 0%,#153556 0,transparent 55%),#091526;color:#eef4ff}
[data-testid="stHeader"]{background:#091526}
.block-container{max-width:1120px;padding-top:2rem;padding-bottom:1.5rem}
[data-testid="stWidgetLabel"] p{color:#bbcade;font-size:12px}
.brand{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:8px 0 20px;border-bottom:1px solid #263b54;margin-bottom:24px}
.brand img{width:155px;max-width:40%;height:auto;border-radius:5px}
.brand small{color:#9fb1ca;font:500 11px 'Segoe UI',sans-serif;letter-spacing:1.5px;text-align:right}
.portal-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:18px}
.portal-heading h1{font:650 30px 'Segoe UI',sans-serif;letter-spacing:-.8px;color:#f2f6ff;margin:0 0 7px;padding:0}
.portal-heading p{font-size:13px;color:#a4b7cf;margin:0}
.heading-badge{border:1px solid #37516b;border-radius:30px;padding:7px 12px;color:#acc5e2;font-size:11px;white-space:nowrap}
.portal-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:4px 0 22px}
.portal-card{--accent:#7bbcff;--tint:#183651;padding:17px 18px 15px;border:1px solid #2a3e57;border-radius:14px;background:linear-gradient(130deg,#14263c,#102035);display:flex;flex-direction:column;min-height:181px;position:relative;overflow:hidden;transition:border-color .15s,transform .15s,box-shadow .15s}
.portal-card:before{content:'';position:absolute;left:0;top:18px;bottom:18px;width:3px;background:var(--accent);border-radius:0 3px 3px 0;opacity:.8}
.portal-card:hover{border-color:var(--accent);transform:translateY(-2px);box-shadow:0 8px 24px #030b1733}
.portal-top{display:flex;justify-content:space-between;align-items:center;gap:10px}
.portal-icon{width:32px;height:32px;display:grid;place-items:center;border-radius:9px;background:var(--tint);color:var(--accent);font-size:12px;font-weight:700;letter-spacing:.5px}
.portal-category{font-size:10px;letter-spacing:.2px;color:var(--accent);background:var(--tint);padding:4px 8px;border-radius:20px}
.portal-card h2{font:600 16px 'Segoe UI',sans-serif;color:#f1f6ff;margin:12px 0 5px;padding:0;letter-spacing:-.2px}
.portal-card p{color:#a8bad0;font-size:12px;line-height:1.5;margin:0 0 14px}
.portal-card a{display:inline-flex;align-items:center;align-self:flex-end;gap:22px;margin-top:auto;padding:7px 12px;min-height:32px;border-radius:8px;background:var(--tint);color:var(--accent)!important;border:1px solid transparent;text-decoration:none!important;font-size:12px;font-weight:600;line-height:1.3}
.portal-card a:hover{border-color:var(--accent);filter:brightness(1.15)}
.portal-card a:focus-visible{outline:3px solid var(--accent);outline-offset:3px}
.portal-footer{color:#8ea3bd;font-size:11px;border-top:1px solid #263b54;padding-top:14px}
@media(max-width:850px){.portal-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:520px){.portal-grid{grid-template-columns:1fr}.portal-heading h1{font-size:26px}.heading-badge{display:none}.brand small{font-size:9px;letter-spacing:.8px}.portal-card{min-height:170px}.portal-card a{min-height:40px;padding:9px 15px}}
@media(prefers-reduced-motion:reduce){.portal-card{transition:none}.portal-card:hover{transform:none}}
</style>""", unsafe_allow_html=True)
st.markdown('<div class="brand"><img src="data:image/png;base64," alt="Ellenco Construções"><small>CONSTRUÇÕES · TECNOLOGIA DA INFORMAÇÃO</small></div>', unsafe_allow_html=True)
st.markdown('<div class="portal-heading"><div><h1>Portal de TI</h1><p>Seus sistemas a um clique.</p></div><span class="heading-badge">ACESSOS RÁPIDOS</span></div>', unsafe_allow_html=True)
left, right = st.columns([2, 1])
with left:
    search = st.text_input("Buscar portal", placeholder="Digite o nome do sistema…")
with right:
    category = st.selectbox("Categoria", ["Todos"] + list(dict.fromkeys(p[1] for p in PORTAIS)))

def normalize(text):
    return "".join(c for c in unicodedata.normalize("NFD", text.lower()) if not unicodedata.combining(c))

filtered = [p for p in PORTAIS if (category == "Todos" or p[1] == category) and normalize(search.strip()) in normalize(p[0] + " " + p[1])]
st.caption(f"{len(filtered)} de {len(PORTAIS)} portais")
COLORS = {
    "Suporte": ("#8ac5ff", "#193653"),
    "Pessoas": ("#c2b0ff", "#2b284c"),
    "Documentos": ("#f3cc88", "#3b3329"),
    "Organização": ("#8ddbd8", "#173b42"),
    "Clockin": ("#87dec0", "#183c38"),
}
cards = []
for name, group, description, url, icon in filtered:
    accent, tint = COLORS[group]
    cards.append(f'<article class="portal-card" style="--accent:{accent};--tint:{tint}"><div class="portal-top"><span class="portal-icon" aria-hidden="true">{escape(icon)}</span><span class="portal-category">{escape(group)}</span></div><h2>{escape(name)}</h2><p>{escape(description)}</p><a href="{escape(url, quote=True)}" target="_blank" rel="noopener noreferrer" aria-label="Acessar {escape(name, quote=True)} em nova aba">Acessar <span aria-hidden="true">↗</span></a></article>')
if cards:
    st.markdown('<div class="portal-grid">' + ''.join(cards) + '</div>', unsafe_allow_html=True)
else:
    st.info("Nenhum portal encontrado. Tente outro nome ou categoria.")
st.markdown('<div class="portal-footer">Ellenco Construções · Os acessos abrem em uma nova aba. Carol Conect requer acesso à rede interna.</div>', unsafe_allow_html=True)
